mapper.select:
SELECT reservation.id FROM model_runtime.platform_model_capability_verification verification
JOIN model_runtime.platform_model_deployment_verification_audit audit ON audit.verification_id = verification.id
JOIN model_runtime.platform_capability_verification_reservation reservation ON reservation.id = audit.reservation_id
WHERE verification.id = #{d.lastVerificationId.value}
  AND verification.platform_model_deployment_id = #{d.id.value}
  AND verification.deployment_revision = #{d.version} - 1
  AND verification.platform_provider_connection_id = #{d.providerConnectionId.value}
  AND verification.platform_provider_connection_revision = #{d.providerConnectionRevision}
  AND verification.model_code = #{d.modelCode} AND verification.succeeded = TRUE
  AND verification.declared_capabilities = verification.observed_capabilities
  AND verification.declared_capabilities::TEXT[] = ARRAY[#{d.modelType}]::TEXT[]
  AND verification.result_code = 'S2_PASSED' AND verification.probed_at <= #{now}
  AND verification.expires_at = #{d.verificationExpiresAt} AND verification.expires_at > #{now}
  AND verification.expires_at <= verification.probed_at + INTERVAL '24 hours'
  AND audit.succeeded = TRUE AND audit.deployment_id = #{d.id.value}
  AND reservation.deployment_id = #{d.id.value} AND reservation.deployment_revision = verification.deployment_revision
  AND reservation.status = 'COMPLETED' AND reservation.outcome = 'PASSED' AND reservation.attempted_requests = 3
  AND reservation.sample_version = #{sampleVersion}
  AND reservation.expected_sample_digests = string_to_array(#{samples}, ',')
  AND reservation.passed_sample_digests = reservation.expected_sample_digests
  AND reservation.inputs_digest = #{inputs} AND reservation.target_fingerprint = #{target}
  AND reservation.completed_at < reservation.deadline AND reservation.completed_at < reservation.quote_expires_at

mapper.insert:
INSERT INTO model_runtime.platform_model_supply_grant(publication_id, tenant_id, status, version, granted_at)
SELECT #{publicationId}, tenant_id, 'ACTIVE', 0, #{now}
FROM unnest(string_to_array(#{tenants}, ',')::BIGINT[]) AS tenant_id
